/**
 * The crew's hours against the target (punch list #255, v2.6585): the lead's signal on the Your week card. Framed as
 * the crew's craft, never a tech's speed: counted only on finished jobs that carry a target, and honest about how many
 * finished with none. A target is the job's open expected hours (`job_expected_hours`, v2.6321), else the labor
 * budget's hours when the office typed one or the bid carried one.
 *
 * Pure. The week is the company's pay week (Sunday to Saturday, `payWeekAnchor`).
 */
import { payWeekContaining, type PayWeek } from '../payWeekAnchor.ts'
import { addDaysYmd } from '../emailSchedule/emailScheduleWeek.ts'

export type TargetJob = {
  jobId: string
  /** "1184 Water heater" */
  label: string
  /** The day the job finished on the company calendar; null while it is still open. */
  finishedYmd: string | null
  /** The open expected hours, else the labor budget's hours, else null: the job carries no target. */
  targetHours: number | null
  /** Every crew member's hours on the job. */
  crewHours: number
}

export type CrewTargetRead = {
  /** Finished in the week with a target. */
  jobs: number
  hours: number
  target: number
  /** Finished in the week with no target, so not counted. */
  noTarget: number
  /** target − hours: positive is under the target. */
  under: number
}

const round1 = (n: number) => Math.round(n * 10) / 10
const inWeek = (ymd: string | null, week: PayWeek): ymd is string => ymd != null && ymd >= week.start && ymd <= week.end

/** The target the signal reads: the open expected hours first, else a labor budget above zero. */
export function targetOf(expectedHours: number | null | undefined, budgetHours: number | null | undefined): number | null {
  if (expectedHours != null && expectedHours > 0) return expectedHours
  if (budgetHours != null && budgetHours > 0) return budgetHours
  return null
}

/** The crew against the target over the jobs finished inside one week. */
export function crewAgainstTarget(jobs: readonly TargetJob[], week: PayWeek): CrewTargetRead {
  let n = 0
  let hours = 0
  let target = 0
  let noTarget = 0
  for (const j of jobs) {
    if (!inWeek(j.finishedYmd, week)) continue
    if (j.targetHours == null || j.targetHours <= 0) {
      noTarget += 1
      continue
    }
    n += 1
    hours += j.crewHours
    target += j.targetHours
  }
  return { jobs: n, hours: round1(hours), target: round1(target), noTarget, under: round1(target - hours) }
}

export type CrewTargetWords = {
  /** "112 h for a 124 h target" or "No finished job with a target this week" */
  head: string
  /** "✓ 12 hours under on 3 jobs", "8 hours over on 3 jobs", "On the target over 2 jobs", or '' with nothing counted. */
  move: string
  /** Up, down, flat, or none: the pill's tone; under the target is up. */
  tone: 'up' | 'down' | 'flat' | 'none'
  /** "One more job finished with no target, so it is not counted." or '' */
  note: string
}

const hoursWord = (h: number): string => `${Math.abs(h) === 1 ? '1 hour' : `${fmt(Math.abs(h))} hours`}`
const fmt = (n: number): string => (Number.isInteger(n) ? String(n) : n.toFixed(1))
const jobsWord = (n: number): string => `${n} ${n === 1 ? 'job' : 'jobs'}`

export function crewTargetWords(read: CrewTargetRead): CrewTargetWords {
  const note =
    read.noTarget === 0
      ? ''
      : read.noTarget === 1
        ? `One more job finished with no target, so it is not counted.`
        : `${read.noTarget} more jobs finished with no target, so they are not counted.`
  if (read.jobs === 0) return { head: 'No finished job with a target this week', move: '', tone: 'none', note }
  const head = `${fmt(read.hours)} h for a ${fmt(read.target)} h target`
  if (Math.abs(read.under) < 0.05) return { head, move: `On the target over ${jobsWord(read.jobs)}`, tone: 'flat', note }
  if (read.under > 0) return { head, move: `✓ ${hoursWord(read.under)} under on ${jobsWord(read.jobs)}`, tone: 'up', note }
  return { head, move: `${hoursWord(read.under)} over on ${jobsWord(read.jobs)}`, tone: 'down', note }
}

/** The last `n` pay weeks ending with the one holding `todayYmd`, oldest first. */
export function lastWeeks(todayYmd: string, n: number): PayWeek[] {
  const out: PayWeek[] = []
  let w = payWeekContaining(todayYmd)
  for (let i = 0; i < n; i++) {
    out.unshift(w)
    w = payWeekContaining(addDaysYmd(w.start, -7))
  }
  return out
}

export type CrewTargetWeek = { week: PayWeek; read: CrewTargetRead }

/** The read for each of the weeks, oldest first: the dots on the card, with the target as the dashed line. */
export function crewTargetWeeks(jobs: readonly TargetJob[], weeks: readonly PayWeek[]): CrewTargetWeek[] {
  return weeks.map((week) => ({ week, read: crewAgainstTarget(jobs, week) }))
}
